private static boolean isTypo(String tag, String valid) {
    if (tag.length() <= 3) return false;
    String s = tag.toLowerCase(Locale.US);
    String t = valid.toLowerCase(Locale.US);
    if (s.equals(t)) return false;
    int diff = Math.abs(s.length() - t.length());
    if (diff > 1) return false;
    if (s.length() == t.length()) {
        int mismatches = 0;
        int mismatchIndex = -1;
        for (int i=0;i<s.length();i++) {
            if (s.charAt(i) != t.charAt(i)) {
                mismatches++;
                if (mismatches > 2) return false;
                mismatchIndex = i;
            }
        }
        if (mismatches == 1) return true;
        if (mismatches == 2) {
            int i = mismatchIndex - 1;
            return i >= 0 && s.charAt(i) == t.charAt(mismatchIndex) && s.charAt(mismatchIndex) == t.charAt(i);
        }
        return false;
    } else {
        // length diff 1: check insertion/deletion
        String longer = s.length() > t.length() ? s : t;
        String shorter = s.length() > t.length() ? t : s;
        int i=0,j=0;
        boolean found = false;
        while (i < shorter.length() && j < longer.length()) {
            if (shorter.charAt(i) == longer.charAt(j)) {
                i++; j++;
            } else if (found) {
                return false;
            } else {
                found = true;
                j++;
            }
        }
        return true;
    }
}

